package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.watch.Notify;
import net.officefloor.hq.app.watch.WatchStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored status change: CLAIM_OPENED, CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED,
 *  CLAIM_REJECTED or CLAIM_VOIDED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>,
 *  then number=<n> when the claim has or had a number, then for CLAIM_SETTLED and CLAIM_APPROVED
 *  due=<0.00> as fixed on settling (n/a when its grade had no rate), for CLAIM_REJECTED reason=<reason>,
 *  for CLAIM_VOIDED of a SETTLED claim reversed=<0.00>, the frozen figure it takes out of the totals (n/a when none),
 *  then for CLAIM_VOIDED reason=<reason> when voided with one.
 *  A claim opened above the review threshold is CLAIM_REVIEW (no number yet); a steward's review of it is
 *  CLAIM_REVIEWED, then CLAIM_OPENED with its number.
 *  A claim settled or approved then tells the person's watchers (NOTIFY), before the figures moved. */
public class AuditClaimStatus {
    public void audit(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, @Val StatusChange change, @Val Rollup before,
            PersonStore people, Audit audit, RollupService rollups, WatchStore watches) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        if (move.from() == ClaimStatus.REVIEW && move.to() == ClaimStatus.OPEN) {
            String which = " sheet=" + claim.getSheetId() + " by=" + input.user() + " person=" + person.getName()
                    + " amount=" + shown.amount() + " date=" + shown.date();
            audit.record(move.to().event(move.from()) + which);
            audit.record(move.to().event() + which + " number=" + change.number());
            rollups.record(claim.getSheetId(), input.user(), before);
            return;
        }
        audit.record(move.to().event(move.from()) + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (change.number() == null ? "" : " number=" + change.number())
                + (move.to() == ClaimStatus.SETTLED ? " due=" + (shown.due() == null ? "n/a" : shown.due()) : "")
                + (move.from() == ClaimStatus.PENDING && move.to() == ClaimStatus.OPEN ? " reason=" + input.reason() : "")
                + (move.from() == ClaimStatus.SETTLED && move.to() == ClaimStatus.VOID
                        ? " reversed=" + (shown.due() == null ? "n/a" : shown.due()) : "")
                + (move.to() == ClaimStatus.VOID && claim.getVoidReason() != null ? " reason=" + claim.getVoidReason() : ""));
        if (move.to() == ClaimStatus.SETTLED) {
            Notify.watchers(watches, audit, person, input.user(), change.number());
        }
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim stands. Only OPEN, PENDING and SETTLED claims count toward the totals; a PENDING claim
 *  (settled by a clerk above the clerk limit, awaiting a steward) is handled as an OPEN one, and a
 *  statement binds it like any other claim that counts. A DELETED claim (a deleted DRAFT) counts nowhere,
 *  and may be restored to a DRAFT only on the sheet's today it was deleted (see {@link CheckClerkLimit}).
 *  A REVIEW claim (opened while its due is above the review threshold in force on its date) awaits a
 *  steward's review, which makes it OPEN; until then it counts in no total and has no number. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim may move from this status to {@code next}: DRAFT to OPEN, OPEN to PENDING or
     *  SETTLED, PENDING to SETTLED (approved) or OPEN (rejected), and DRAFT, OPEN or PENDING to VOID;
     *  SETTLED to VOID too, though only a steward within days of settling it (see {@link CheckClerkLimit}).
     *  DRAFT to DELETED, and DELETED back to DRAFT (restored). DRAFT to REVIEW (opened above the review
     *  threshold), REVIEW to OPEN (reviewed) or VOID. VOID is final. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
            case REVIEW -> this == DRAFT;
        };
    }

    /** Whether a claim of this status may move to another person: DRAFT, OPEN or PENDING. */
    public boolean canMove() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DELETED -> "CLAIM_DELETED";
            case DRAFT -> "CLAIM_DRAFTED";
            case REVIEW -> "CLAIM_REVIEW";
        };
    }

    /** The audit event recorded when a claim moves from {@code from} to this status: a PENDING claim
     *  settled is CLAIM_APPROVED, one moved back to OPEN is CLAIM_REJECTED, and a DELETED claim moved
     *  back to DRAFT is CLAIM_RESTORED. A REVIEW claim moved to OPEN is CLAIM_REVIEWED (then recorded
     *  as CLAIM_OPENED too, see {@link AuditClaimStatus}). */
    public String event(ClaimStatus from) {
        if (from == DELETED && this == DRAFT) {
            return "CLAIM_RESTORED";
        }
        if (from == PENDING && this == SETTLED) {
            return "CLAIM_APPROVED";
        }
        if (from == PENDING && this == OPEN) {
            return "CLAIM_REJECTED";
        }
        if (from == REVIEW && this == OPEN) {
            return "CLAIM_REVIEWED";
        }
        return event();
    }
}
